using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so preserve the old property name.
            entity.HasDiscriminator().HasJsonPropertyName("Discriminator");

            // Breaking change 2: EF 9 uses only the raw key for "id" (e.g. "1").
            // Existing documents have id = "Blog|1", so preserve the old format.
            entity.HasIdProperty(b => b.Id, useDiscriminatorPrefix: true);

            // Breaking change 3: EF 9 no longer supports HasIndex on Cosmos.
            // Indexes are managed in the Azure portal / IaC, not EF.
            // Removed: entity.HasIndex(b => b.Name);
        });
    }
}
